\set ON_ERROR_STOP on
BEGIN READ ONLY;
SET LOCAL statement_timeout = '280s';
\copy (WITH s AS (SELECT id, company_id, chat_id, channel, started_at, had_handoff, handoff_at, resolved_at, status FROM conversation_sessions WHERE started_at >= '@FROM@'::timestamptz AND started_at < '@TO@'::timestamptz), m AS (SELECT s.id sid, x.* FROM s CROSS JOIN LATERAL (SELECT mm.timestamp ts, mm.is_from_customer cust, mm.is_from_ai ai, coalesce(mm.content,'') content, mm.media_type FROM messages mm WHERE mm.conversation_session_id = s.id ORDER BY mm.timestamp LIMIT 12) x), fr AS (SELECT DISTINCT ON (sid) sid, ai FROM m WHERE NOT cust ORDER BY sid, ts), firsthuman AS (SELECT sid, min(ts) hts FROM m WHERE NOT cust AND NOT ai GROUP BY sid), w AS (SELECT m.*, row_number() OVER (PARTITION BY m.sid ORDER BY m.ts) rn, lag(m.ts) OVER (PARTITION BY m.sid, m.cust ORDER BY m.ts) prev_same FROM m LEFT JOIN firsthuman f ON f.sid = m.sid WHERE f.hts IS NULL OR m.ts < f.hts), w4 AS (SELECT * FROM w WHERE rn <= 4), agg AS (SELECT sid, count(*) n_window, max(ts) t4, count(*) FILTER (WHERE cust) w_customer_msgs, count(*) FILTER (WHERE ai) w_ai_msgs, avg(length(content)) FILTER (WHERE cust) cust_chars_mean, max(length(content)) FILTER (WHERE cust) cust_chars_max, sum(length(content) - length(replace(content, '?', ''))) FILTER (WHERE cust) cust_question_marks, extract(epoch FROM (min(ts) FILTER (WHERE ai) - min(ts) FILTER (WHERE cust))) first_ai_reply_s, avg(extract(epoch FROM (ts - prev_same))) FILTER (WHERE cust AND prev_same IS NOT NULL) cust_gap_mean_s, avg(length(content)) FILTER (WHERE ai) ai_chars_mean FROM w4 GROUP BY sid), base AS (SELECT s.*, a.* FROM s JOIN fr ON fr.sid = s.id AND fr.ai JOIN agg a ON a.sid = s.id WHERE a.n_window = 4 AND a.w_customer_msgs >= 1), ev AS (SELECT b.sid, (SELECT min(e.escalated_at) FROM escalation_events e WHERE e.conversation_session_id = b.sid OR (e.conversation_session_id IS NULL AND e.chat_id = b.chat_id AND e.escalated_at >= b.started_at AND e.escalated_at < b.started_at + interval '7 days')) esc_at, (SELECT min(hm.timestamp) FROM messages hm WHERE hm.conversation_session_id = b.sid AND NOT hm.is_from_customer AND NOT hm.is_from_ai) human_at, (SELECT max(lm.timestamp) FROM messages lm WHERE lm.conversation_session_id = b.sid) last_at FROM base b) SELECT (b.started_at AT TIME ZONE 'UTC')::date fecha, b.channel, extract(hour FROM b.started_at AT TIME ZONE 'America/Bogota')::int hour_local, extract(isodow FROM b.started_at AT TIME ZONE 'America/Bogota')::int dow, b.w_customer_msgs, b.w_ai_msgs, round(b.cust_chars_mean::numeric, 1) cust_chars_mean, b.cust_chars_max, b.cust_question_marks, round(b.first_ai_reply_s::numeric, 1) first_ai_reply_s, round(b.cust_gap_mean_s::numeric, 1) cust_gap_mean_s, round(b.ai_chars_mean::numeric, 1) ai_chars_mean, (b.had_handoff OR b.status IN ('transferred', 'abandoned') OR ev.human_at IS NOT NULL)::int needed_human, b.status, b.had_handoff::int had_handoff, (SELECT count(*) FROM w4 WHERE w4.sid = b.sid AND b.handoff_at IS NOT NULL AND w4.ts >= b.handoff_at) w_msgs_after_handoff, (SELECT count(*) FROM w4 WHERE w4.sid = b.sid AND ev.esc_at IS NOT NULL AND w4.ts >= ev.esc_at) w_msgs_after_esc, round(extract(epoch FROM b.handoff_at - b.t4)::numeric, 1) handoff_rel_s, round(extract(epoch FROM ev.esc_at - b.t4)::numeric, 1) esc_rel_s, round(extract(epoch FROM ev.human_at - b.t4)::numeric, 1) human_rel_s, round(extract(epoch FROM b.resolved_at - b.t4)::numeric, 1) resolved_rel_s, round(extract(epoch FROM ev.last_at - b.t4)::numeric, 1) last_msg_rel_s FROM base b JOIN ev ON ev.sid = b.sid) TO STDOUT WITH CSV HEADER
COMMIT;
